//! Value-only recipe plans, generated by TypeScript or authored as JSON.
//! Each case gets a fresh app, input state and virtual clock; only renderer resources are shared.
use crate::{CaptureError, CapturedFrame, HostView, PreviewSession, PreviewViewport, Source};
use plico::VirtualClock;
use plico_renderer::{SemanticRole, SemanticSnapshot, TextContext};
use plico_runtime::testing::{Command, dispatch};
use serde::{Deserialize, Serialize};
use snafu::Snafu;
use std::{
    collections::HashSet,
    path::Path,
    time::{Duration, Instant},
};

#[derive(Debug, Snafu)]
pub enum RecipeError {
    #[snafu(display("invalid recipe plan: {message}"))]
    Invalid { message: String },
    #[snafu(display("recipe failed: {message}"))]
    Failed { message: String },
    #[snafu(display("recipe I/O: {source}"))]
    Io { source: std::io::Error },
    #[snafu(display("recipe capture: {source}"))]
    Capture { source: CaptureError },
    #[snafu(display("recipe input: {source}"))]
    Input {
        source: plico_runtime::testing::Error,
    },
}
#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct RecipePlan<S> {
    pub version: u32,
    pub cases: Vec<RecipeCase<S>>,
}
#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct RecipeCase<S> {
    pub name: String,
    pub state: S,
    pub viewport: PreviewViewport,
    pub steps: Vec<RecipeStep>,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Location {
    pub file: String,
    pub line: u32,
    pub column: u32,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct RecipeStep {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source: Option<Location>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub flow: Vec<String>,
    pub operation: Operation,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(tag = "op", rename_all = "snake_case", deny_unknown_fields)]
pub enum Operation {
    Command {
        command: Command,
    },
    Fill {
        label: String,
        text: String,
        #[serde(default)]
        occurrence: Option<usize>,
    },
    Advance {
        milliseconds: u64,
    },
    Assert {
        assertion: Assertion,
    },
    /// Advance the virtual clock until an assertion passes or its deterministic
    /// timeout expires. This never sleeps on wall-clock time.
    Wait {
        assertion: Assertion,
        timeout_ms: u64,
        #[serde(default = "default_wait_interval_ms")]
        interval_ms: u64,
    },
    Capture {
        name: String,
    },
    /// Application-defined value injected through a synthetic host/service boundary.
    Event {
        event: serde_json::Value,
    },
}
#[derive(Clone, Debug, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Selector {
    #[serde(default)]
    pub role: Option<String>,
    #[serde(default)]
    pub label: Option<String>,
    #[serde(default)]
    pub label_prefix: Option<String>,
    #[serde(default)]
    pub occurrence: Option<usize>,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Assertion {
    Nodes {
        selector: Selector,
        expect: NodeExpectation,
    },
    /// Exact rendered text, independent of accessibility label exposure.
    Text { text: String, present: bool },
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum NodeExpectation {
    Exists,
    Absent,
    Count { count: usize },
    Enabled { enabled: bool },
    Value { value: String },
    Selected { selected: bool },
}
fn default_wait_interval_ms() -> u64 {
    16
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RecipeMode {
    Semantic,
    Visual,
}
#[derive(Debug, Serialize)]
pub struct NodeEvidence {
    pub role: String,
    pub label: Option<String>,
    pub value: Option<String>,
    pub bounds: [f32; 4],
    pub disabled: bool,
    pub selected: Option<bool>,
}
#[derive(Debug, Serialize)]
pub struct StepResult {
    pub index: usize,
    pub source: Option<Location>,
    pub flow: Vec<String>,
    pub passed: bool,
    pub milliseconds: f64,
    pub virtual_time_ms: u128,
    pub screenshot: Option<String>,
    pub error: Option<String>,
}
#[derive(Debug, Serialize)]
pub struct RecipeResult {
    pub name: String,
    pub passed: bool,
    pub milliseconds: f64,
    pub steps: Vec<StepResult>,
    pub error: Option<String>,
    pub failure_screenshot: Option<String>,
    pub last_screenshot: Option<String>,
    pub evidence: Vec<NodeEvidence>,
    pub rendered_text: Vec<String>,
}
fn invalid(message: impl Into<String>) -> RecipeError {
    RecipeError::Invalid {
        message: message.into(),
    }
}
fn failed(message: impl Into<String>) -> RecipeError {
    RecipeError::Failed {
        message: message.into(),
    }
}
fn safe_name(name: &str) -> bool {
    !name.is_empty()
        && name
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_'))
}
fn validate_assertion(assertion: &Assertion) -> Result<(), RecipeError> {
    if let Assertion::Nodes { selector, .. } = assertion {
        if let Some(role) = &selector.role
            && SemanticRole::from_name(role).is_none()
        {
            return Err(invalid(format!("unknown selector role {role:?}")));
        }
        if selector.label.is_some() && selector.label_prefix.is_some() {
            return Err(invalid("selector cannot combine label and label_prefix"));
        }
    }
    Ok(())
}
impl<S> RecipePlan<S> {
    /// Validate all cases before writing artifacts or invoking application factories.
    pub fn validate(&self) -> Result<(), RecipeError> {
        if self.version != 1 {
            return Err(invalid(format!("unsupported version {}", self.version)));
        }
        if self.cases.is_empty() {
            return Err(invalid("plan has no cases"));
        }
        let mut names = HashSet::new();
        for case in &self.cases {
            if !safe_name(&case.name) || !names.insert(&case.name) {
                return Err(invalid(format!(
                    "unsafe or duplicate case name {:?}",
                    case.name
                )));
            }
            let v = case.viewport;
            if v.width == 0
                || v.height == 0
                || !v.scale.is_finite()
                || v.scale <= 0.
                || v.scale > 8.
                || v.width as f64 * v.scale > 8192.
                || v.height as f64 * v.scale > 8192.
            {
                return Err(invalid(format!("invalid viewport in {}", case.name)));
            }
            let mut captures = HashSet::new();
            for step in &case.steps {
                match &step.operation {
                    Operation::Capture { name }
                        if !safe_name(name) || name == "_failure" || !captures.insert(name) =>
                    {
                        return Err(invalid(format!(
                            "unsafe or duplicate capture name {name:?} in {}",
                            case.name
                        )));
                    }
                    Operation::Assert { assertion } => validate_assertion(assertion)?,
                    Operation::Wait {
                        assertion,
                        timeout_ms,
                        interval_ms,
                    } => {
                        validate_assertion(assertion)?;
                        if !(1..=300_000).contains(timeout_ms)
                            || *interval_ms == 0
                            || interval_ms > timeout_ms
                        {
                            return Err(invalid(format!(
                                "wait in {} requires 1..=300000 timeout_ms and 1..=timeout interval_ms",
                                case.name
                            )));
                        }
                    }
                    _ => {}
                }
            }
        }
        Ok(())
    }
    /// Ordinary case failures are recorded and do not prevent later cases from running.
    /// `event` receives owned fixture data, never runtime handles from the plan.
    pub fn run<V: HostView>(
        self,
        session: &mut PreviewSession,
        mode: RecipeMode,
        output: &Path,
        mut create: impl FnMut(S) -> V,
        mut event: impl FnMut(&mut V, &serde_json::Value) -> Result<(), String>,
    ) -> Result<Vec<RecipeResult>, RecipeError> {
        self.validate()?;
        std::fs::create_dir_all(output).map_err(|source| RecipeError::Io { source })?;
        let mut results = Vec::new();
        for case in self.cases {
            let directory = output.join(&case.name);
            std::fs::create_dir_all(&directory).map_err(|source| RecipeError::Io { source })?;
            // Remove only artifacts owned by this invocation, never arbitrary directory contents.
            for name in std::iter::once("_failure").chain(case.steps.iter().filter_map(|step| {
                match &step.operation {
                    Operation::Capture { name } => Some(name.as_str()),
                    _ => None,
                }
            })) {
                let path = directory.join(format!("{name}.png"));
                if path.exists() {
                    std::fs::remove_file(path).map_err(|source| RecipeError::Io { source })?;
                }
            }
            results.push(run_case(
                case,
                session,
                mode,
                &directory,
                &mut create,
                &mut event,
            ));
        }
        Ok(results)
    }
}
fn frame<V: HostView>(
    source: &mut Source<V>,
    text: &mut TextContext,
    viewport: PreviewViewport,
) -> Result<(), RecipeError> {
    source
        .try_build_frame(text, viewport.width, viewport.height)
        .map_err(|error| failed(error.to_string()))?;
    if source
        .placed_nodes()
        .iter()
        .any(|n| !n.rect.iter().all(|x| x.is_finite()))
    {
        return Err(failed("non-finite layout bounds"));
    }
    Ok(())
}
fn check<V: HostView>(source: &Source<V>, assertion: &Assertion) -> Result<(), RecipeError> {
    match assertion {
        Assertion::Text { text, present } => {
            let found = source
                .placed_nodes()
                .iter()
                .any(|node| node.paint.text.as_deref() == Some(text));
            if found != *present {
                return Err(failed(format!(
                    "text {text:?}: expected present={present}, got {found}"
                )));
            }
        }
        Assertion::Nodes { selector, expect } => {
            let snapshot = source.semantics();
            let matches: Vec<_> = snapshot
                .exposed_nodes()
                .into_iter()
                .filter(|n| {
                    selector.role.as_ref().is_none_or(|r| n.role.as_str() == r)
                        && selector
                            .label
                            .as_ref()
                            .is_none_or(|l| n.label.as_ref() == Some(l))
                        && selector
                            .label_prefix
                            .as_ref()
                            .is_none_or(|p| n.label.as_ref().is_some_and(|l| l.starts_with(p)))
                })
                .collect();
            let nodes = if let Some(index) = selector.occurrence {
                matches.get(index).copied().into_iter().collect()
            } else {
                matches
            };
            let success = match expect {
                NodeExpectation::Exists => !nodes.is_empty(),
                NodeExpectation::Absent => nodes.is_empty(),
                NodeExpectation::Count { count } => nodes.len() == *count,
                NodeExpectation::Enabled { enabled } => {
                    nodes.len() == 1 && nodes[0].disabled != *enabled
                }
                NodeExpectation::Value { value } => {
                    nodes.len() == 1 && nodes[0].value.as_ref() == Some(value)
                }
                NodeExpectation::Selected { selected } => {
                    nodes.len() == 1 && nodes[0].states.selected == Some(*selected)
                }
            };
            if !success {
                return Err(failed(format!(
                    "selector {selector:?}: expected {expect:?}; matched {} nodes: {:?}",
                    nodes.len(),
                    nodes
                        .iter()
                        .map(|node| (&node.label, &node.value, node.disabled))
                        .collect::<Vec<_>>()
                )));
            }
        }
    }
    Ok(())
}
#[derive(Clone, Copy)]
struct WaitTiming {
    timeout_ms: u64,
    interval_ms: u64,
}
fn wait_for<V: HostView>(
    source: &mut Source<V>,
    text: &mut TextContext,
    viewport: PreviewViewport,
    clock: &VirtualClock,
    now_ms: &mut u128,
    assertion: &Assertion,
    timing: WaitTiming,
) -> Result<(), RecipeError> {
    let mut last_failure = match check(source, assertion) {
        Ok(()) => return Ok(()),
        Err(error) => error,
    };
    let mut elapsed = 0;
    while elapsed < timing.timeout_ms {
        let delta = timing.interval_ms.min(timing.timeout_ms - elapsed);
        clock
            .advance(Duration::from_millis(delta))
            .map_err(|_| failed("virtual clock overflow"))?;
        *now_ms += u128::from(delta);
        elapsed += delta;
        frame(source, text, viewport)?;
        match check(source, assertion) {
            Ok(()) => return Ok(()),
            Err(error) => last_failure = error,
        }
    }
    Err(failed(format!(
        "wait timed out after {} ms: {last_failure}",
        timing.timeout_ms
    )))
}
fn evidence(snapshot: &SemanticSnapshot) -> Vec<NodeEvidence> {
    snapshot
        .exposed_nodes()
        .into_iter()
        .map(|n| NodeEvidence {
            role: n.role.as_str().into(),
            label: n.label.clone(),
            value: n.value.clone(),
            bounds: n.bounds,
            disabled: n.disabled,
            selected: n.states.selected,
        })
        .collect()
}
fn capture<V: HostView>(
    source: &mut Source<V>,
    text: &mut TextContext,
    renderer: &mut crate::capture::CaptureRenderer,
    viewport: PreviewViewport,
) -> Result<CapturedFrame, RecipeError> {
    crate::capture(source)
        .size(viewport.width, viewport.height)
        .scale(viewport.scale)
        .render_with_borrowed(renderer, text)
        .map_err(|source| RecipeError::Capture { source })
}
fn run_case<S, V: HostView>(
    case: RecipeCase<S>,
    session: &mut PreviewSession,
    mode: RecipeMode,
    directory: &Path,
    create: &mut impl FnMut(S) -> V,
    event: &mut impl FnMut(&mut V, &serde_json::Value) -> Result<(), String>,
) -> RecipeResult {
    let started = Instant::now();
    let mut result = RecipeResult {
        name: case.name,
        passed: false,
        milliseconds: 0.,
        steps: vec![],
        error: None,
        failure_screenshot: None,
        last_screenshot: None,
        evidence: vec![],
        rendered_text: vec![],
    };
    let v = case.viewport;
    let clock = VirtualClock::default();
    let mut now_ms = 0u128;
    let mut source = Source::with_clock(create(case.state), clock.clone());
    let mut text = TextContext::new();
    let execute = (|| -> Result<(), RecipeError> {
        let (width, height) = crate::capture::dimensions(v.width, v.height, v.scale)
            .map_err(|source| RecipeError::Capture { source })?;
        let mut renderer = if mode == RecipeMode::Visual {
            Some(
                session
                    .renderer(width, height)
                    .map_err(|source| RecipeError::Capture { source })?,
            )
        } else {
            None
        };
        if let Some(renderer) = renderer.as_deref_mut() {
            renderer
                .configure_text(&mut text, v.scale)
                .map_err(|source| RecipeError::Capture { source })?;
        }
        frame(&mut source, &mut text, v)?;
        for (index, step) in case.steps.into_iter().enumerate() {
            let started = Instant::now();
            let mut screenshot = None;
            let operation = (|| -> Result<(), RecipeError> {
                match step.operation {
                    Operation::Command { command } => dispatch(&mut source, &mut text, &command)
                        .map_err(|source| RecipeError::Input { source })?,
                    Operation::Fill {
                        label,
                        text: value,
                        occurrence,
                    } => {
                        let commands = [
                            Command::Focus {
                                role: "textbox".into(),
                                label,
                                occurrence,
                            },
                            Command::KeyEvent {
                                event: plico_renderer::KeyEvent {
                                    phase: plico_renderer::KeyPhase::Down,
                                    key: "a".into(),
                                    key_without_modifiers: "a".into(),
                                    code: "KeyA".into(),
                                    text: None,
                                    text_with_all_modifiers: None,
                                    location: plico_renderer::KeyLocation::Standard,
                                    modifiers: if cfg!(target_os = "macos") {
                                        plico::Modifiers::META
                                    } else {
                                        plico::Modifiers::CONTROL
                                    },
                                    repeat: false,
                                    synthetic: false,
                                },
                            },
                            Command::Key {
                                key: "Backspace".into(),
                            },
                            Command::Text { text: value },
                        ];
                        for command in commands {
                            dispatch(&mut source, &mut text, &command)
                                .map_err(|source| RecipeError::Input { source })?;
                            frame(&mut source, &mut text, v)?;
                        }
                    }
                    Operation::Advance { milliseconds } => {
                        clock
                            .advance(Duration::from_millis(milliseconds))
                            .map_err(|_| failed("virtual clock overflow"))?;
                        now_ms += u128::from(milliseconds);
                    }
                    Operation::Assert { assertion } => check(&source, &assertion)?,
                    Operation::Wait {
                        assertion,
                        timeout_ms,
                        interval_ms,
                    } => wait_for(
                        &mut source,
                        &mut text,
                        v,
                        &clock,
                        &mut now_ms,
                        &assertion,
                        WaitTiming {
                            timeout_ms,
                            interval_ms,
                        },
                    )?,
                    Operation::Event { event: value } => {
                        source.update(|view| event(view, &value)).map_err(failed)?;
                    }
                    Operation::Capture { name } => {
                        if let Some(renderer) = renderer.as_deref_mut() {
                            let image = capture(&mut source, &mut text, renderer, v)?;
                            image
                                .write_png(directory.join(format!("{name}.png")))
                                .map_err(|source| RecipeError::Capture { source })?;
                            screenshot = Some(format!("{}/{name}.png", result.name));
                            result.last_screenshot.clone_from(&screenshot);
                        }
                    }
                }
                frame(&mut source, &mut text, v)
            })();
            result.steps.push(StepResult {
                index: index + 1,
                source: step.source,
                flow: step.flow,
                passed: operation.is_ok(),
                milliseconds: started.elapsed().as_secs_f64() * 1000.,
                virtual_time_ms: now_ms,
                screenshot,
                error: operation.as_ref().err().map(ToString::to_string),
            });
            if operation.is_err()
                && let Some(renderer) = renderer.as_deref_mut()
            {
                match capture(&mut source, &mut text, renderer, v).and_then(|image| {
                    image
                        .write_png(directory.join("_failure.png"))
                        .map_err(|source| RecipeError::Capture { source })
                }) {
                    Ok(()) => {
                        result.failure_screenshot = Some(format!("{}/_failure.png", result.name))
                    }
                    Err(error) => result
                        .steps
                        .last_mut()
                        .unwrap()
                        .error
                        .as_mut()
                        .unwrap()
                        .push_str(&format!("; failure capture: {error}")),
                }
            }
            operation?;
        }
        Ok(())
    })();
    if execute.is_err() {
        result.evidence = evidence(&source.semantics());
        result.rendered_text = source
            .placed_nodes()
            .iter()
            .filter_map(|node| node.paint.text.as_deref().map(str::to_owned))
            .collect();
    }
    result.passed = execute.is_ok();
    result.error = execute.err().map(|error| error.to_string());
    result.milliseconds = started.elapsed().as_secs_f64() * 1000.;
    result
}
